66	std::string number_text(double value)
67	{
68	    std::ostringstream out;
69	    out.precision(2);
70	    out << std::fixed << value;
71	    std::string text = out.str();
72	    while (text.size() > 3 && text.back() == '0')
73	        text.pop_back();
74	    return text;
75	}
