395	// -- The session's tools ----------------------------------------------------
396	
397	std::optional<ToolError> PrinterConversation::preflight_tool(ToolHandler handler, ToolActivity& activity) const
398	{
399	    // Every session is offered every printer tool, so the tool list stays the
400	    // same for the prompt cache; what a call may do depends on the session.
401	    // Finding and adding a printer belongs to an Add session: a Change or
402	    // Connect session is about a printer the person already has, and an add
403	    // there would save another printer and move the session onto it.
404	    if (m_mode != ConversationMode::Add && (handler == ToolHandler::PrinterIdentify || handler == ToolHandler::PrinterAdd))
405	        return ToolError{"not_in_this_conversation",
406	                         "This conversation is about " + m_printer_name + ", which is already set up; printers are not "
407	                         "found or added here. Tell the person that another printer is added with + Add printer on Home."};
408	    // The settings tools reach the project too; here they reach this
409	    // printer's own settings, and nothing else.
410	    if (handler == ToolHandler::SettingsSearch || handler == ToolHandler::SettingsGet ||
411	        handler == ToolHandler::SettingsPreviewPatch || handler == ToolHandler::SettingsApplyPatch) {
412	        if (m_printer_name.empty())
413	            return ToolError{"no_printer", "No printer is set up in this conversation yet: add one first."};
414	        const json arguments = json::parse(activity.arguments_json);
415	        if (arguments.value("scope", std::string()) != "printer")
416	            return ToolError{"not_in_this_conversation", "Only this printer's settings are changed here: pass scope printer and "
417	                                                         "target.preset \"" + m_printer_name + "\"."};
418	        if (arguments.at("target").value("preset", std::string()) != m_printer_name)
419	            return ToolError{"other_printer", "This conversation can change only \"" + m_printer_name + "\". Another saved printer is "
420	                                              "changed from Printer settings… in its menu on Home."};
421	        return std::nullopt;
422	    }
423	    // A stock profile holds nothing of the person's own: a nozzle size or a
424	    // connection is saved on a printer they have added.
425	    if (about().stock && (handler == ToolHandler::PrinterChange || handler == ToolHandler::PrinterConnect ||
426	                          handler == ToolHandler::PrinterConnectionStatus))
427	        return ToolError{"stock_profile", "\"" + m_printer_name + "\" is the settings JusPrin comes with for this model, not a "
428	                                          "printer the person has added, so its nozzle and connection are not saved. Its other "
429	                                          "settings are changed by saving a copy, which is then theirs (settings_apply_patch with "
430	                                          "persistAs). To keep a nozzle or a connection, they add the printer with + Add printer "
431	                                          "on Home."};
432	    // A change is to the printer this session is about, and only once there
433	    // is one. The model sometimes names a printer on the network instead.
434	    if (handler == ToolHandler::PrinterChange) {
435	        if (saved(m_printer_name).name.empty())
436	            return ToolError{"no_printer", "No printer is set up in this conversation yet: add one first."};
437	        const std::string name = json::parse(activity.arguments_json).value("printerName", std::string());
438	        if (name != m_printer_name)
439	            return ToolError{saved(name).name.empty() ? "unknown_printer" : "other_printer",
440	                             "This conversation can change only \"" + m_printer_name + "\". Another saved printer is "
441	                             "changed from Printer settings… in its menu on Home."};
442	        return std::nullopt;
443	    }
444	    if (handler != ToolHandler::PrinterConnect)
445	        return std::nullopt;
446	    json              arguments = json::parse(activity.arguments_json);
447	    const std::string name      = m_printer_name;
448	    if (saved(name).name.empty())
449	        return ToolError{"no_printer", "There is no saved printer to connect yet: add one first."};
450	
451	    const PrinterConnectionInfo info = m_backend.connection(name);
452	    // No printer can be listed without the plug-in, so the reason is that,
453	    // not an unknown device.
454	    if (info.needs_network_plugin)
455	        return ToolError{"connection_unavailable", info.message};
456	    if (info.provider == "bambu") {
457	        // The person names the printer as its list shows it, so its name
458	        // finds it as surely as its id.
459	        const std::string device = arguments.value("deviceId", std::string());
460	        const auto found = std::find_if(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& candidate) {
461	            return offered(candidate) && (candidate.id == device || candidate.name == device);
462	        });
463	        // A call written for a print host reaches this branch with an address
464	        // instead of an id, and may be naming a printer the app has seen.
465	        if (found == info.candidates.end())
466	            return ToolError{"unknown_device", unknown_device_text(info, device.empty() ? arguments.value("address", std::string()) : device)};
467	        activity.title = "Connect to " + found->name;
468	        arguments["deviceId"] = found->id;
469	        arguments["target"]   = found->name;
470	    } else if (info.provider == "host") {
471	        // The registry has already refused a hostType without an address; a
472	        // deviceId here names a Bambu Lab printer this one is not.
473	        if (!arguments.contains("hostType"))
474	            return ToolError{"address_needed", "Pass hostType and the address the person gave."};
475	        activity.title      = "Connect to " + arguments["address"].get<std::string>();
476	        arguments["target"] = arguments["address"];
477	    } else
478	        return ToolError{"connection_unavailable", info.message};
479	    // Which field the local form asks for, and the printer it named.
480	    arguments["provider"]    = info.provider;
481	    arguments["printerName"] = name;
482	    activity.arguments_json = arguments.dump();
483	    return std::nullopt;
484	}
485	
486	std::string PrinterConversation::unknown_device_text(const PrinterConnectionInfo& info, const std::string& asked) const
487	{
488	    // What it was asked for may be a printer the app has seen and does not
489	    // offer. An empty id or address is not a match for one with none known.
490	    const auto wanted = std::find_if(info.candidates.begin(), info.candidates.end(), [&asked](const ConnectionCandidate& candidate) {
491	        return !offered(candidate) && !asked.empty() && (candidate.id == asked || candidate.name == asked || candidate.address == asked);
492	    });
493	    if (wanted != info.candidates.end())
494	        return not_offered_text(*wanted) + " It cannot be connected as it is." +
495	               (in_cloud_mode(*wanted) ? std::string(" ") + kPersonsChoice : std::string());
496	
497	    std::string listed;
498	    std::string others;
499	    bool        cloud = false;
500	    for (const ConnectionCandidate& candidate : info.candidates)
501	        if (offered(candidate))
502	            listed += (listed.empty() ? "" : ", ") + candidate.id + " (" + candidate.name + ")";
503	        else {
504	            others += " " + not_offered_text(candidate);
505	            cloud = cloud || in_cloud_mode(candidate);
506	        }
507	    return (listed.empty() ? search_text() : "Pass the deviceId of one of these printers in LAN mode: " + listed + ".") + others +
508	           (cloud ? std::string(" ") + kPersonsChoice : std::string());
509	}
510	
511	std::string PrinterConversation::search_text() const
512	{
513	    if (!m_search)
514	        return "No network search has run yet in this conversation; printer_connection_status starts it.";
515	    const std::string seconds =
516	        std::to_string(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - m_search->started).count());
517	    if (m_search->port != DiscoveryPort::Ours)
518	        return m_search->port == DiscoveryPort::Taken ? kPortTaken : kNotListening;
519	    if (!m_search->said_none && !m_search->found)
520	        return "The network search started " + seconds + " seconds ago and has found no printer of this model yet. The app posts a note "
521	               "when one appears, or after about " + std::to_string(kSearchWait.count()) + " seconds with none.";
522	    return "The network search has listened for " + seconds + " seconds and has found no printer of this model in LAN mode." +
523	           (m_search->found ? "" : " The app posts a note if one appears.");
524	}
525	
526	json PrinterConversation::search_json(const PrinterConnectionInfo& info) const
527	{
528	    if (info.provider != "bambu")
529	        return json{{"state", "not_applicable"}};
530	    if (!m_search || info.state == "unavailable")
531	        return json{{"state", "not_started"}};
532	    return json{{"state", m_search->port == DiscoveryPort::Taken ? "port_taken" :
533	                          m_search->port == DiscoveryPort::Free  ? "not_listening" :
534	                          m_search->said_none || m_search->found ? "listening" :
535	                                                                   "started"},
536	                {"secondsAgo", std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - m_search->started).count()}};
537	}
