564	void PrinterConversation::tool_settled(const ToolActivity& activity)
565	{
566	    if (activity.tool != "settings_apply_patch" || activity.state != Agent::ToolState::Succeeded)
567	        return;
568	    const std::string saved_as = json::parse(activity.result_json).value("savedAs", std::string());
569	    if (saved_as.empty() || saved_as == m_printer_name)
570	        return;
571	    // Saved as a copy, which Orca selected in the preset's place: the
572	    // printer the person now has, and Home lists it.
573	    m_printer_name = saved_as;
574	    m_host.printers_changed(saved_as);
575	    m_host.session_changed();
576	}
577	
578	Result PrinterConversation::identify(const json& arguments, const std::string& message_id)
579	{
580	    std::vector<const CatalogPrinter*> printers;
581	    for (const json& id : arguments.at("catalogIds")) {
582	        const CatalogPrinter* printer = catalog_entry(id);
583	        if (printer == nullptr)
584	            return refuse("unknown_printer", "\"" + id.get<std::string>() + "\" is not on the printer list; copy it exactly from the printer list.");
585	        if (std::find(printers.begin(), printers.end(), printer) == printers.end())
586	            printers.push_back(printer);
587	    }
588	    if (printers.size() > kMaximumCandidates)
589	        return refuse("too_many", "More than three fit. Ask one question that narrows it down instead.");
590	    const bool stated = said_nozzle(arguments);
591	    for (const CatalogPrinter* printer : printers)
592	        if (stated && !ships(printer->nozzles, arguments["nozzle"].get<double>()))
593	            return unknown_nozzle(printer->nozzles, printer->display_name(), arguments["nozzle"].get<double>());
594	
595	    json cards = json::array();
596	    json found = json::array();
597	    const std::vector<SavedPrinter> mine = m_backend.saved_printers();
598	    for (const CatalogPrinter* printer : printers) {
599	        const double nozzle = stated ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
600	        const bool   yours  = std::any_of(mine.begin(), mine.end(), [&](const SavedPrinter& p) { return p.model_id == printer->model_id; });
601	        cards.push_back(json{{"catalogId", printer->id}, {"name", printer->display_name()},
602	                             {"buildVolume", printer->build_volume}, {"picture", picture_data_url(printer->picture)}});
603	        found.push_back(json{{"catalogId", printer->id},
604	                             {"brand", printer->vendor_name},
605	                             {"model", printer->model_name},
606	                             {"buildVolume", printer->build_volume},
607	                             {"nozzles", printer->nozzles},
608	                             {"assumed", json{{"nozzle", nozzle},
609	                                              {"plate", nullable(printer->default_plate)},
610	                                              {"filament", nullable(printer->filament_for(nozzle))}}},
611	                             {"alreadyYours", yours}});
612	    }
613	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
614	                            {"kind", "printers"}, {"printers", std::move(cards)}});
615	    m_host.session_changed();
616	    return ok(json{{"printers", std::move(found)}});
617	}
618	
619	Result PrinterConversation::add(const json& arguments, const std::string& message_id)
620	{
621	    const std::string     id      = arguments.at("catalogId");
622	    const CatalogPrinter* printer = catalog_entry(id);
623	    if (printer == nullptr)
624	        return refuse("unknown_printer", "\"" + id + "\" is not on the printer list; copy it exactly from the printer list.");
625	    const double nozzle = said_nozzle(arguments) ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
626	    if (!ships(printer->nozzles, nozzle))
627	        return unknown_nozzle(printer->nozzles, printer->display_name(), nozzle);
628	    // A second yes to the same printer is the same printer, not another one.
629	    if (const auto added = m_added.find(id); added != m_added.end())
630	        return refuse("already_added", "This conversation already added " + printer->display_name() + " as \"" + added->second +
631	                                           "\". To change it, use printer_change. A second printer of the same model is added by "
632	                                           "opening Add printer again.");
633	
634	    // Adding never authenticates: credentials belong to connecting, so a
635	    // failed connection cannot repeat this save.
636	    AddPrinterRequest request{printer->vendor_id,           printer->model_id,        number_text(nozzle),
637	                              printer->filament_for(nozzle), printer->display_name(), {}};
638	    SavedPrinter      added;
639	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
640	        return refuse("add_failed", problem);
641	    const SavedPrinter now = saved(added.name);
642	    if (now.name.empty())
643	        throw std::logic_error("A successful add did not save a printer");
644	    m_printer_name = now.name;
645	    m_added[id]    = now.name;
646	    // The receipt is the app's, drawn from what was saved: the model's reply
647	    // can word the moment any way, but whether it happened is not its to say.
648	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
649	                            {"kind", "added"}, {"printer", json{{"name", now.name}, {"nozzle", now.nozzle}}}});
650	    m_host.printers_changed(now.name);
651	    m_host.session_changed();
652	    return ok(json{{"printer", printer_json(now)}});
653	}
654	
655	Result PrinterConversation::change(const json& arguments)
656	{
657	    // preflight_tool has checked that this is the session's own printer.
658	    const std::string  name = arguments.at("printerName");
659	    const SavedPrinter now  = saved(name);
660	    // What is loaded is the printer's to report, not the conversation's to
661	    // record: the nozzle is the one physical change this tool saves.
662	    if (!said_nozzle(arguments))
663	        return refuse("nothing_to_change", "Name the nozzle size that changed.");
664	    if (!now.nozzles.empty() && !ships(now.nozzles, arguments["nozzle"].get<double>()))
665	        return unknown_nozzle(now.nozzles, now.model.empty() ? now.name : now.model, arguments["nozzle"].get<double>());
666	
667	    ChangePrinterRequest request;
668	    request.name = name;
669	    if (arguments["nozzle"].get<double>() != now.nozzle)
670	        request.nozzle = arguments["nozzle"].get<double>();
671	    if (!request.nozzle)
672	        return refuse("nothing_to_change", "That is already how " + name + " is set up.");
673	
674	    SavedPrinter             changed;
675	    std::vector<std::string> discarded;
676	    if (const std::string problem = m_backend.change_printer(request, changed, discarded); !problem.empty())
677	        return refuse("change_failed", problem);
678	    const SavedPrinter after = saved(name);
679	    json               what  = json::array();
680	    what.push_back(json{{"field", "nozzle"}, {"before", now.nozzle}, {"after", after.nozzle}});
681	    m_host.printers_changed();
682	    m_host.session_changed();
683	    return ok(json{{"changed", std::move(what)}, {"discarded", discarded}, {"printer", printer_json(after)}});
684	}
685	
686	Result PrinterConversation::connection_status(const std::string& name, const std::string& message_id)
687	{
688	    if (saved(name).name.empty())
689	        return refuse("no_printer", "There is no saved printer to connect yet: add one first.");
690	    // For a Bambu Lab printer this starts looking for it on the network, once;
691	    // see m_prepared.
692	    if (m_prepared != name) {
693	        m_backend.prepare_connection(name);
694	        m_prepared = name;
695	        m_search.reset();
696	    }
697	    const PrinterConnectionInfo info = m_backend.connection(name);
698	    if (info.needs_network_plugin)
699	        show_plugin_needed(message_id);
700	    if (!m_search && info.provider == "bambu" && info.state != "unavailable")
701	        m_search = NetworkSearch{std::chrono::steady_clock::now()};
702	    // What this read lists, the model now knows: no note need say it again.
703	    // A printer already reached needs no search to report on, however it is
704	    // reached.
705	    if (m_search && (found_on_network(info) || info.state == "verified"))
706	        m_search->found = true;
707	    return ok(connection_json(info, search_json(info)));
708	}
