719	void PrinterConversation::connect(const json& arguments, const std::string& credential)
720	{
721	    const std::string name   = arguments.at("printerName");
722	    const std::string target = arguments.at("target");
723	    const std::string problem =
724	        arguments.at("provider") == "bambu" ?
725	            m_backend.connect_printer(name, arguments.at("deviceId"), credential) :
726	            m_backend.connect_host(name, arguments.at("hostType"), arguments.at("address"), credential);
727	    if (!problem.empty()) {
728	        m_host.post_note("Connection to " + target + " failed: " + problem);
729	        m_host.session_changed();
730	        m_host.start_turn();
731	        return;
732	    }
733	    m_connecting = name;
734	    m_last_look  = {};
735	    m_host.session_changed();
736	}
