738	void PrinterConversation::abandon_connection()
739	{
740	    if (m_connecting.empty())
741	        return;
742	    m_backend.cancel_connection(m_connecting);
743	    m_connecting.clear();
744	}
745	
746	void PrinterConversation::tick(std::chrono::steady_clock::time_point now)
747	{
748	    if (m_form && m_form->reading.valid() && m_form->reading.wait_for(std::chrono::seconds(0)) == std::future_status::ready) {
749	        m_form->options = m_form->reading.get();
750	        m_host.session_changed();
751	    }
752	    watch_search(now);
753	    if (m_connecting.empty() || now - m_last_look < kConnectionLook)
754	        return;
755	    m_last_look = now;
756	    const PrinterConnectionInfo info = m_backend.connection(m_connecting);
757	    if (info.state == "connecting")
758	        return;
759	    const std::string name = m_connecting;
760	    m_connecting.clear();
761	    m_host.post_note(info.state == "verified" ? "Connection to " + name + " verified." :
762	                                                "Connection to " + name + " failed: " + info.message);
763	    m_host.printers_changed();
764	    m_host.session_changed();
765	    m_host.start_turn();
766	}
767	
768	void PrinterConversation::watch_search(std::chrono::steady_clock::time_point now)
769	{
770	    // An attempt under way is read by tick alone: reading a connection can
771	    // settle it.
772	    if (!m_search || m_search->found || !m_connecting.empty() ||
773	        now - m_search->last_look < (m_search->said_none || m_search->port != DiscoveryPort::Ours ? std::chrono::seconds(kSearchLateLook) :
774	                                                                                                       std::chrono::seconds(kConnectionLook)))
775	        return;
776	    m_search->last_look = now;
777	    const PrinterConnectionInfo info = m_backend.connection(m_prepared);
778	    // The printer was renamed or removed, or nothing can reach the network now.
779	    if (info.provider != "bambu" || info.state == "unavailable") {
780	        m_search.reset();
781	        return;
782	    }
783	    if (info.state == "verified") {
784	        m_search->found = true;
785	        return;
786	    }
787	    std::string note;
788	    if (found_on_network(info)) {
789	        m_search->found = true;
790	        bool cloud = false;
791	        for (const ConnectionCandidate& candidate : info.candidates) {
792	            if (candidate.account_only)
793	                continue;
794	            cloud = cloud || in_cloud_mode(candidate);
795	            if (offered(candidate))
796	                note += (note.empty() ? "The network search found " : "; ") + with_address(candidate) + " in LAN mode, which can be connected";
797	            else if (in_cloud_mode(candidate))
798	                note += (note.empty() ? "The network search found " : "; ") + with_address(candidate) +
799	                        " with LAN Only off, which cannot be connected as it is";
800	            else
801	                // Heard, and not this printer: said as such, so "found no
802	                // printer of this model" is never the note about a printer
803	                // the app saw.
804	                note += (note.empty() ? "The network search heard a printer it does not offer: " : "; ") + not_offered_text(candidate);
805	        }
806	        note += ".";
807	        if (cloud)
808	            note += std::string(" ") + kPersonsChoice;
809	    } else if (now - m_search->started < kSearchWait)
810	        return;
811	    else {
812	        // Checked only once discovery has had time to bind: the check itself
813	        // binds the port for a moment, which could cost discovery its own bind.
814	        const DiscoveryPort port = m_backend.discovery_port();
815	        if (port == m_search->port && (port != DiscoveryPort::Ours || m_search->said_none))
816	            return;
817	        m_search->port = port;
818	        if (port == DiscoveryPort::Taken)
819	            note = kPortTaken;
820	        else if (port == DiscoveryPort::Free)
821	            note = kNotListening;
822	        else {
823	            m_search->said_none = true;
824	            note = "The network search has listened for " + std::to_string(kSearchWait.count()) +
825	                   " seconds and has found no printer of this model. The app posts another note if one appears.";
826	        }
827	    }
828	    m_host.post_note(note);
829	    m_host.session_changed();
830	    m_host.start_turn();
831	}
832	
833	// -- The panel's own page --------------------------------------------------
834	
835	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
836	{
837	    if (type == "printer_instructions") {
838	        // Bounded: the page's words become every request's system prompt.
839	        const std::string text = payload.value("text", std::string());
840	        if (text.size() <= kInstructionsLimit && text != m_instructions) {
841	            m_instructions = text;
842	            m_host.profile_changed();
843	        }
844	        return true;
845	    }
846	    if (type == "printer_opening") {
847	        // The first line is the page's to write and the app's to post, once:
848	        // a reloaded page asks again, and the thread already has it.
849	        const std::string text = payload.value("text", std::string());
850	        if (m_opened || text.empty() || text.size() > kNoteLimit)
851	            return true;
852	        m_opened                     = true;
853	        const std::string message_id = m_host.post_opening(text);
854	        for (json& entry : m_blocks)
855	            if (entry.value("afterMessageId", std::string()).empty())
856	                entry["afterMessageId"] = message_id;
857	        m_host.session_changed();
858	        return true;
859	    }
860	    if (type != "printer_action")
861	        return false;
862	
863	    const std::string action = payload.value("action", std::string());
864	    if (action == "close")
865	        m_host.close_panel();
866	    else if (action == "manual_setup")
867	        open_form();
868	    else if (action == "form_options")
869	        ask_form_options(payload);
870	    else if (action == "form_finish")
871	        finish_form(payload);
872	    else if (action == "form_close") {
873	        m_form.reset();
874	        m_host.session_changed();
875	    } else if (action == "orca_printer_list") {
876	        // OrcaSlicer's own printer list, for a panel whose page could not
877	        // load and so cannot show the form; what it added is news the model
878	        // answers.
879	        const ManualPrinterResult result = m_backend.run_manual_setup();
880	        if (!result.added.empty()) {
881	            m_printer_name = result.added.front().name;
882	            m_host.post_note("The person added " + m_printer_name + " from the printer list.");
883	            m_host.printers_changed(m_printer_name);
884	            m_host.session_changed();
885	            m_host.start_turn();
886	        }
887	    } else if (action == "connect" && payload.value("actionId", std::string()) == m_credential_action &&
888	               payload.contains("credential") && payload["credential"].is_string()) {
889	        const json arguments = std::move(m_credential_arguments);
890	        m_credential_action.clear();
891	        m_credential_arguments = json::object();
892	        connect(arguments, payload["credential"].get<std::string>());
893	    } else if (action == "open_printer_settings" && !m_printer_name.empty()) {
894	        m_backend.open_printer_settings(m_printer_name);
895	        m_host.printers_changed();
896	        m_host.session_changed();
897	    } else if (action == "undo_add")
898	        undo_add(payload.value("blockId", std::string()));
899	    else if (action == "install_network_plugin")
900	        install_network_plugin();
901	    return true;
902	}
903	
904	void PrinterConversation::undo_add(const std::string& block_id)
905	{
906	    json* receipt = nullptr;
907	    for (json& block : m_blocks)
908	        if (block.value("id", std::string()) == block_id && block.value("kind", std::string()) == "added")
909	            receipt = &block;
910	    // A second tap that arrived before the page redrew the first has nothing
911	    // left to undo.
912	    if (receipt == nullptr || receipt->value("removed", false))
913	        return;
914	
915	    // Orca's own delete, as Home's "Remove printer…" runs it: the printer the
916	    // project was set up for gives way to the profile it was based on.
917	    const std::string name = receipt->at("printer").at("name");
918	    if (const std::string problem = m_backend.remove_printer(name); !problem.empty()) {
919	        m_host.post_note("Undo did not remove " + name + ": " + problem);
920	        m_host.session_changed();
921	        return;
922	    }
923	    // printer_add saves a printer based on a shipped profile, which Orca
924	    // deletes without asking; only a printer of the person's own design can
925	    // be kept by declining there.
926	    if (!saved(name).name.empty())
927	        throw std::logic_error("Removing an added printer left it saved");
928	
929	    if (m_connecting == name)
930	        abandon_connection();
931	    (*receipt)["removed"] = true;
932	    // The same printer can now be added again, and nothing here is about it.
933	    for (auto added = m_added.begin(); added != m_added.end();)
934	        added = added->second == name ? m_added.erase(added) : std::next(added);
935	    if (m_printer_name == name)
936	        m_printer_name.clear();
937	    if (m_prepared == name) {
938	        m_prepared.clear();
939	        m_search.reset();
940	    }
941	    m_host.post_note("The person tapped Undo on the receipt: " + name + " is removed and is no longer one of their printers.");
942	    m_host.printers_changed();
943	    m_host.session_changed();
944	    m_host.start_turn();
945	}
946	
947	// -- The printer form --------------------------------------------------------
948	
949	void PrinterConversation::open_form()
950	{
951	    // A printer is added in an Add session only, as printer_add is.
952	    if (m_mode != ConversationMode::Add)
953	        return;
954	    // An earlier form's read is waited for first: the backend's copy of the
955	    // person's own presets is what that read is using.
956	    m_form.reset();
957	    m_backend.prepare_setup_options();
958	    PrinterForm form;
959	    // A machine that already has a printer is that printer, and the form
960	    // adds new ones; a model the catalogue lacks cannot be set up from it.
961	    const std::vector<SavedPrinter> printers = m_backend.saved_printers();
962	    for (DiscoveredPrinter& found : m_backend.nearby_printers()) {
963	        if (std::any_of(printers.begin(), printers.end(),
964	                        [&found](const SavedPrinter& printer) { return printer.device_id == found.stable_id; }))
965	            continue;
966	        const auto& catalog = m_backend.catalog();
967	        const auto  model   = std::find_if(catalog.begin(), catalog.end(), [&found](const CatalogPrinter& printer) {
968	            return !printer.device_model_id.empty() && printer.device_model_id == found.device_model_id;
969	        });
970	        if (model != catalog.end())
971	            form.nearby.emplace_back(std::move(found), model->id);
972	    }
973	    m_form = std::move(form);
974	    m_host.session_changed();
975	}
976	
977	void PrinterConversation::ask_form_options(const json& payload)
978	{
979	    if (!m_form)
980	        return;
981	    const std::string     id      = payload.value("catalogId", std::string());
982	    const double          nozzle  = payload.value("nozzle", 0.);
983	    const CatalogPrinter* printer = catalog_entry(id);
984	    if (printer == nullptr || !ships(printer->nozzles, nozzle))
985	        return;
986	    if (m_form->asked_id == id && m_form->asked_nozzle == nozzle)
987	        return;
988	    m_form->asked_id     = id;
989	    m_form->asked_nozzle = nozzle;
990	    m_form->options.reset();
991	    m_form->error.clear();
992	    // A read still running for the last choice is waited for here; its
993	    // answer is no longer wanted.
994	    m_form->reading = std::async(std::launch::async, [&backend = m_backend, id, nozzle] { return backend.setup_options(id, nozzle); });
995	    m_host.session_changed();
996	}
997	
998	void PrinterConversation::finish_form(const json& payload)
999	{
1000	    if (!m_form)
1001	        return;
1002	    const std::string     id      = payload.value("catalogId", std::string());
1003	    const double          nozzle  = payload.value("nozzle", 0.);
1004	    const CatalogPrinter* printer = catalog_entry(id);
1005	    // The page finishes from the options it was sent; anything else is a
1006	    // page out of step with the app, and nothing is saved from it.
1007	    const auto refuse_form = [this](const std::string& why) {
1008	        m_form->error = why;
1009	        m_host.session_changed();
1010	    };
1011	    const std::optional<SetupOptions>& options = m_form->options;
1012	    if (printer == nullptr || !options || options->catalog_id != id || options->nozzle != nozzle || !options->error.empty())
1013	        return refuse_form("The form was out of date. Choose the printer again.");
1014	
1015	    std::optional<int> plate;
1016	    std::string        plate_label;
1017	    if (!options->plates.empty()) {
1018	        const int  type  = payload.value("plate", 0);
1019	        const auto found = std::find_if(options->plates.begin(), options->plates.end(),
1020	                                        [type](const PlateOption& option) { return option.type == type; });
1021	        if (found == options->plates.end())
1022	            return refuse_form("Choose the plate on this printer.");
1023	        plate       = type;
1024	        plate_label = found->label;
1025	    }
1026	
1027	    // The filament to start with: one that fits, which is installed with
1028	    // the printer; one of the person's own; one made for other printers,
1029	    // which is copied for this one; or a preset the person makes in
1030	    // OrcaSlicer's Create filament window once the printer is added.
1031	    const bool        create   = payload.value("create", false);
1032	    const std::string filament = create ? std::string() : payload.value("filament", std::string());
1033	    const auto        in       = [&filament](const std::vector<FilamentOption>& list) -> const FilamentOption* {
1034	        const auto found = std::find_if(list.begin(), list.end(), [&filament](const FilamentOption& option) { return option.name == filament; });
1035	        return found == list.end() ? nullptr : &*found;
1036	    };
1037	    const FilamentOption* fitting = filament.empty() ? nullptr : in(options->filaments);
1038	    const FilamentOption* other   = filament.empty() ? nullptr : in(options->others);
1039	    const FilamentOption* own     = filament.empty() ? nullptr : in(options->own);
1040	    if (!filament.empty() && fitting == nullptr && other == nullptr && own == nullptr)
1041	        return refuse_form("That filament is no longer on the list. Choose another.");
1042	
1043	    const std::string device = payload.value("deviceId", std::string());
1044	    const auto        found  = std::find_if(m_form->nearby.begin(), m_form->nearby.end(),
1045	                                            [&device](const auto& entry) { return entry.first.stable_id == device; });
1046	    if (!device.empty() && (found == m_form->nearby.end() || found->second != id))
1047	        return refuse_form("That printer is no longer on the list. Choose it again.");
1048	
1049	    // The printer is installed with a filament that fits: the chosen one, or
1050	    // the profile's default until the chosen one is in place.
1051	    AddPrinterRequest request{printer->vendor_id, printer->model_id, number_text(nozzle),
1052	                              fitting != nullptr ? fitting->name : options->default_filament, printer->display_name(), device, plate};
1053	    SavedPrinter      added;
1054	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
1055	        return refuse_form(problem);
1056	    const SavedPrinter now = saved(added.name);
1057	    if (now.name.empty())
1058	        throw std::logic_error("A successful add did not save a printer");
1059	
1060	    const auto label_of = [&options](const std::string& name) {
1061	        for (const auto* list : {&options->filaments, &options->others, &options->own})
1062	            for (const FilamentOption& option : *list)
1063	                if (option.name == name)
1064	                    return option.label;
1065	        return name;
1066	    };
1067	    std::string starting = fitting != nullptr ? fitting->label : label_of(options->default_filament);
1068	    std::string filament_note;
1069	    if (own != nullptr || other != nullptr) {
1070	        const FilamentOption& chosen = own != nullptr ? *own : *other;
1071	        const bool            copy   = !chosen.made_for.empty();
1072	        std::string           used;
1073	        if (const std::string problem = m_backend.start_with_filament(now.name, chosen.name, copy, used); !problem.empty())
1074	            filament_note = " " + chosen.label + " could not be used: " + problem + " It starts with " + starting + ".";
1075	        else if (copy)
1076	            starting = "a copy of " + chosen.label + " saved for this printer as " + used;
1077	        else
1078	            starting = "their own preset " + used;
1079	    }
1080	    if (create) {
1081	        const std::string made = m_backend.create_filament_preset(now.name);
1082	        filament_note = made.empty() ? " The person opened the Create filament window and made no preset for this printer, so it starts with " +
1083	                                           starting + "."
1084	                                     : " The person made the filament preset " + made + " in the Create filament window; it is in slot 1.";
1085	    }
1086	
