1042	void AgentHost::handle_skills(const std::string& envelope_id, const std::string& payload_json)
1043	{
1044	    // Every skill in one message, sorted by name. A skill has a trigger, a
1045	    // description or both, and at most one has each trigger: the host fires
1046	    // a skill by the event its trigger names, and the model reads a
1047	    // described one by name. A payload that breaks a rule is refused whole
1048	    // and the skills received before stay in force.
1049	    constexpr std::size_t kSkillTextLimit        = 16 * 1024;
1050	    constexpr std::size_t kSkillDescriptionLimit = 300;
1051	    constexpr std::size_t kSkillsPayloadLimit    = 256 * 1024;
1052	    const json parsed = payload_json.size() <= kSkillsPayloadLimit ? json::parse(payload_json, nullptr, false) : json();
1053	    bool valid = parsed.is_object() && parsed.size() == 1 && parsed.contains("skills") && parsed["skills"].is_array();
1054	    std::vector<AgentSkill> received;
1055	    std::set<std::string>   triggers;
1056	    if (valid)
1057	        for (const json& value : parsed["skills"]) {
1058	            valid = value.is_object();
1059	            if (valid)
1060	                for (const auto& [key, field] : value.items())
1061	                    valid = valid && field.is_string() &&
1062	                            (key == "name" || key == "trigger" || key == "description" || key == "text");
1063	            if (!valid)
1064	                break;
1065	            AgentSkill skill{value.value("name", ""), value.value("trigger", ""), value.value("description", ""),
1066	                             value.value("text", "")};
1067	            const bool trigger_ok     = !value.contains("trigger") ||
1068	                                        (valid_skill_word_list(skill.trigger, '_') && triggers.insert(skill.trigger).second);
1069	            const bool description_ok = !value.contains("description") ||
1070	                                        (!skill.description.empty() && skill.description.size() <= kSkillDescriptionLimit &&
1071	                                         skill.description.find_first_of("\r\n") == std::string::npos);
1072	            if (!valid_skill_word_list(skill.name, '-') || skill.text.empty() || skill.text.size() > kSkillTextLimit ||
1073	                (skill.trigger.empty() && skill.description.empty()) || !trigger_ok || !description_ok ||
1074	                (!received.empty() && skill.name <= received.back().name)) {
1075	                valid = false;
1076	                break;
1077	            }
1078	            received.push_back(std::move(skill));
1079	        }
1080	    if (!valid) {
1081	        send_bridge_error("invalid_payload", "The project skills are invalid.", envelope_id);
1082	        return;
1083	    }
1084	    m_skills          = std::move(received);
1085	    m_skills_received = true;
1086	    // A turn the app started before the page had sent them waited in the
1087	    // queue; see begin_reply.
1088	    start_next_queued_reply();
1089	}
