1191	void AgentHost::handle_hello(const std::string& envelope_id, const std::string& payload_json)
1192	{
1193	    const json payload = json::parse(payload_json, nullptr, false);
1194	    std::vector<int> versions;
1195	    if (payload.is_object() && payload.contains("protocolVersions") && payload["protocolVersions"].is_array())
1196	        for (const json& value : payload["protocolVersions"])
1197	            if (value.is_number_integer())
1198	                versions.push_back(value.get<int>());
1199	
1200	    if (std::find(versions.begin(), versions.end(), Protocol::kVersion) == versions.end()) {
1201	        m_handshake = false;
1202	        send_envelope(Protocol::kHelloReject,
1203	                      json{{"supportedVersions", json::array({Protocol::kVersion})},
1204	                           {"message", "This build speaks jusprin-agent-bridge version " +
1205	                                           std::to_string(Protocol::kVersion) + " only."}}
1206	                          .dump(),
1207	                      envelope_id);
1208	        return;
1209	    }
1210	
1211	    // Capabilities are informational: the host reports what it can do and the
1212	    // page hides what the host did not claim.
1213	    m_handshake = true;
1214	    json capabilities = json::array();
1215	    for (const std::string& capability : Protocol::capabilities())
1216	        capabilities.push_back(capability);
1217	    send_envelope(Protocol::kHelloAck,
1218	                  json{{"version", Protocol::kVersion},
1219	                       {"capabilities", std::move(capabilities)},
1220	                       {"agent", json{{"status", availability_name(m_availability)}}},
1221	                       {"appearance", m_dark ? "dark" : "light"}}
1222	                      .dump(),
1223	                  envelope_id);
1224	    send_state();
1225	    send_setup_keys();
1226	    if (m_model_source) {
1227	        send_model_catalog();
1228	        request_model_lists();
1229	    }
1230	    if (!m_held_confirmation.empty())
1231	        send_envelope(Protocol::kConfirm, std::exchange(m_held_confirmation, {}));
1232	    if (m_handshake_listener)
1233	        m_handshake_listener();
1234	}
