161	void PrinterPanel::tear_down_runtime()
162	{
163	    m_pump.Stop();
164	    m_settled.reset();
165	    if (!m_web_view)
166	        return;
167	    GetSizer()->Detach(m_web_view.get());
168	
169	    // On macOS a new web view installs its script message handler from a
170	    // CallAfter (WebView::CreateWebView), and wx waits for WebKit's reply to
171	    // that install inside a nested event loop, with the app's
172	    // is_adding_script_handler() flag set until it returns. A view destroyed
173	    // during that wait is called back by WebKit after it is gone, and the app
174	    // crashes. So while any view is mid-install, this runtime is hidden, cut
175	    // off from the session, and destroyed once the install is over -- the same
176	    // wait GUI_App::run_wizard makes.
177	    if (wxGetApp().is_adding_script_handler()) {
178	        m_web_view->Hide();
179	        Agent::AgentHost& host = m_web_view->host();
180	        host.set_session_state_provider({});
181	        host.set_page_message_handler({});
182	        host.set_session_tool_executor({});
183	        m_retired.push_back({std::move(m_persistence), std::move(m_web_view)});
184	        m_release_timer.StartOnce(kReleaseRetryMs);
185	        return;
186	    }
187	
188	    // Deleted here rather than handed to wx: the host inside it holds this
189	    // session's document by reference, and that document goes next. Both
190	    // callers are outside the view's own event handling -- open() comes from
191	    // the shell, close() from a CallAfter -- which is what makes this safe.
192	    m_web_view.reset();
193	    m_persistence.reset();
194	}
