317	// by its name, and for one OrcaSlicer ships, the copy a change is saved as.
318	nlohmann::json PrinterPanel::filament_session_json() const
319	{
320	    const PresetCollection& filaments = wxGetApp().preset_bundle->filaments;
321	    const Preset*           preset    = filaments.find_preset(m_filament_preset, false);
322	
323	    if (preset == nullptr)
324	        throw std::logic_error("The filament chat is about a preset that is not there: " + m_filament_preset);
325	    const auto*    types   = preset->config.option<ConfigOptionStrings>("filament_type");
326	    nlohmann::json session = {{"kind", "filament"},
327	                              {"slot", m_filament_slot + 1},
328	                              {"preset", preset->name},
329	                              {"shown", m_filament_name},
330	                              {"material", types != nullptr && !types->values.empty() ? types->values.front() : std::string()},
331	                              {"stock", preset->is_system}};
332	    if (preset->is_system)
333	        session["copyName"] = Printers::copy_name(preset->name, [&filaments](const std::string& candidate) {
334	            return std::any_of(filaments.begin(), filaments.end(),
335	                               [&candidate](const Preset& other) { return boost::iequals(other.name, candidate); });
336	        });
337	    return session;
