std::string without_secrets(const std::string& text)
{
    static const std::regex key("sk-[A-Za-z0-9_-]{6,}");
    static const std::regex token("[A-Za-z0-9]{6,}");
    const std::string       no_keys = std::regex_replace(text, key, "[hidden]");
